import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, vec4, float, mix, uniform } from 'three/tsl';
import { Mesh, PlaneGeometry, DoubleSide } from 'three/webgpu';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height, 1, 1);
  const material = new MeshStandardNodeMaterial({
    side: DoubleSide,
    metalness: 0.35,
    roughness: 0.6,
  });

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = ctx.textureLoader.SRGBColorSpace || map.colorSpace;

  const uvNode = uv();
  const baseColor = texture(map, uvNode);

  // engineered gradient overlay: subtle vertical tint from ink to surface,
  // plus a faint grain-like modulation using uv-based pseudo-noise
  const grainAmount = uniform(0.035);
  const gradTop = vec4(0.086, 0.086, 0.114, 1.0); // #16161d
  const gradBottom = vec4(0.043, 0.043, 0.063, 1.0); // #0b0b10

  const gradientMix = mix(gradBottom, gradTop, uvNode.y);

  const pseudoNoise = uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233));
  const grain = pseudoNoise.sin().mul(43758.5453).fract().sub(0.5).mul(grainAmount.mul(2.0));

  const combined = baseColor.mul(0.88).add(gradientMix.mul(0.12)).add(vec4(grain, grain, grain, 0.0));

  material.colorNode = combined;

  const mesh = new Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return mesh;
}
